import sys
import heapq

def main():
    import sys
    import heapq
    input = sys.stdin.read().split()
    idx = 0
    n = int(input[idx])
    q = int(input[idx + 1])
    idx += 2
    edges = []
    for _ in range(2 * n - 2):
        ai = int(input[idx])
        bi = int(input[idx + 1])
        ci = int(input[idx + 2])
        edges.append((ai, bi, ci))
        idx += 3
    tree_edges = edges[:n - 1]
    back_edges = edges[n - 1:]
    graph = {i: [] for i in range(1, n + 1)}
    for ai, bi, ci in tree_edges:
        graph[ai].append((bi, ci))
    back_graph = {i: [] for i in range(1, n + 2)}
    for ai, bi, ci in back_edges:
        back_graph[ai].append((1, ci))
    dist = [float('inf')] * (n + 1)
    dist[1] = 0
    pq = [(0, 1)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))
    back_dist = [float('inf')] * (n + 1)
    back_dist[1] = 0
    pq = [(0, 1, 1)]
    while pq:
        d, u, p = heapq.heappop(pq)
        if d > back_dist[u]:
            continue
        for v, w in back_graph[u]:
            if back_dist[u] + w < back_dist[v]:
                back_dist[v] = back_dist[u] + w
                heapq.heappush(pq, (back_dist[v], v, u))
    edge_map = {(ai, bi): ci for ai, bi, ci in edges}
    for _ in range(q):
        t = int(input[idx])
        if t == 1:
            i = int(input[idx + 1])
            w = int(input[idx + 2])
            idx += 3
            ai, bi, ci = edges[i - 1]
            edge_map[(ai, bi)] = w
            if bi == 1:
                dist[ai] = min(dist[ai], dist[bi] + w)
                pq = [(dist[ai], ai)]
                while pq:
                    d, u = heapq.heappop(pq)
                    if d > dist[u]:
                        continue
                    for v, w in graph[u]:
                        if dist[u] + w < dist[v]:
                            dist[v] = dist[u] + w
                            heapq.heappush(pq, (dist[v], v))
            else:
                back_dist[ai] = min(back_dist[ai], back_dist[bi] + w)
                pq = [(back_dist[ai], ai, 1)]
                while pq:
                    d, u, p = heapq.heappop(pq)
                    if d > back_dist[u]:
                        continue
                    for v, w in back_graph[u]:
                        if back_dist[u] + w < back_dist[v]:
                            back_dist[v] = back_dist[u] + w
                            heapq.heappush(pq, (back_dist[v], v, u))

        elif t == 2:
            u = int(input[idx + 1])
            v = int(input[idx + 2])
            idx += 3
            if u == v:
                print(0)
            elif v == 1:
                print(dist[u])
            else:
                print(dist[u] + back_dist[v])

if __name__ == "__main__":
    main()
